"""Shared Amicus header injected into deployed pages, preserving native controls."""
from pathlib import Path
import re
import sys

CSS = "\n.amicus-shell{--am-bg:#fbfaf5;--am-fg:#123244;--am-muted:#526a77;--am-line:#d8d3c6;--am-gold:#a57829;--am-role:#f5efd9;--am-role-fg:#645530;--am-role-line:#d4c6a1}\nhtml[data-theme=\"dark\"] .amicus-shell{--am-bg:#10222e;--am-fg:#ebeff1;--am-muted:#c5d2d8;--am-line:#2c4a5c;--am-gold:#e6c27a;--am-role:#3b3425;--am-role-fg:#e6c27a;--am-role-line:#806b47}\nheader.amicus-shell{background:var(--am-bg)!important;border-bottom:1px solid var(--am-line)!important}\n.amicus-shell .amicus-brand{display:flex!important;flex:0 0 auto;align-items:center;gap:12px;min-width:0;padding:0 10px 0 0}\n.amicus-shell .amicus-brand svg{width:24px;height:27px;flex:none;fill:var(--am-gold)}\n.amicus-shell .amicus-identity{display:flex;flex-direction:column;gap:1px}\n.amicus-shell .amicus-eyebrow{font:400 9.5px/1.4 SFMono-Regular,Consolas,monospace!important;letter-spacing:.16em!important;color:var(--am-muted)!important;text-transform:uppercase;text-decoration:none!important;white-space:nowrap}\n.amicus-shell .amicus-title-row{display:flex;align-items:baseline;gap:11px;white-space:nowrap}\n.amicus-shell .amicus-title{font:650 20px/1.1 Figtree,\"Segoe UI\",system-ui,sans-serif!important;letter-spacing:-.035em!important;color:var(--am-fg)!important;text-decoration:none!important}\n.amicus-shell .amicus-title em{color:var(--am-gold);font-family:Georgia,serif;font-weight:400}\n.amicus-shell .amicus-office{font:500 11px/1.2 Figtree,\"Segoe UI\",system-ui,sans-serif!important;letter-spacing:0!important;text-decoration:none!important;color:var(--am-fg)!important;border-left:1px solid var(--am-line)!important;padding-left:11px!important}\n.amicus-shell .amicus-eyebrow:hover,.amicus-shell .amicus-office:hover{text-decoration:underline!important}\n.amicus-shell .amicus-legacy-brand{display:none!important}\n.amicus-shell .amicus-context{font:500 11px Figtree,system-ui,sans-serif;color:var(--am-muted)}\n.amicus-shell .amicus-actions{display:inline-flex!important;align-items:center;gap:4px;margin-left:auto;flex:0 0 auto;white-space:nowrap}\n.amicus-shell .amicus-actions button.amicus-control,.amicus-shell .amicus-actions .ac-sair,.amicus-shell .amicus-actions .ac-btn{display:inline-flex;align-items:center;justify-content:center;min-width:30px!important;min-height:30px!important;padding:5px 7px!important;background:transparent!important;border:0!important;box-shadow:none!important;border-radius:4px!important;color:var(--am-fg)!important;cursor:pointer}\n.amicus-shell .amicus-control svg,.amicus-shell .ac-sair svg{width:15px;height:15px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}\n.amicus-shell .amicus-actions button:hover{background:color-mix(in srgb,var(--am-fg) 6%,transparent)!important}\n.amicus-shell .amicus-control>span{display:none!important}\n.amicus-shell .amicus-actions .ac-chip,.amicus-shell .amicus-session{display:inline-flex!important;align-items:center;gap:8px;padding-left:12px;margin-left:6px;border-left:1px solid var(--am-line);min-height:30px;color:var(--am-fg);white-space:nowrap}\n.amicus-shell .amicus-actions .ac-chip:empty,.amicus-shell .amicus-session[hidden]{display:none!important}\n.amicus-shell .amicus-actions .ac-u{font:700 12px Figtree,system-ui,sans-serif!important;letter-spacing:0;text-transform:none;color:var(--am-fg)!important;max-width:130px;overflow:hidden;text-overflow:ellipsis}\n.amicus-shell .amicus-actions .ac-p{font:400 9px SFMono-Regular,Consolas,monospace!important;letter-spacing:.1em;text-transform:uppercase;border:1px solid var(--am-role-line)!important;background:var(--am-role)!important;color:var(--am-role-fg)!important;border-radius:0!important;padding:2px 6px!important}\n.amicus-shell .amicus-actions .amicus-enter{font:500 11px Figtree,system-ui,sans-serif;color:var(--am-fg)}\n.amicus-home-header{display:flex!important;align-items:center;gap:12px;padding:10px clamp(18px,4vw,48px)!important}\n@media(max-width:760px){.amicus-shell .amicus-brand{gap:7px;padding-right:0}.amicus-shell .amicus-title{font-size:18px!important}.amicus-shell .amicus-actions{flex-wrap:nowrap;gap:1px}.amicus-shell .amicus-actions .ac-u{max-width:85px}.amicus-shell .amicus-actions .ac-chip,.amicus-shell .amicus-session{gap:4px;margin-left:3px;padding-left:6px}}\n\nhtml[data-theme=\"dark\"]:has(.amicus-home-header) {background:#10222e;color:#ebeff1}html[data-theme=\"dark\"]:has(.amicus-home-header) :is(main p,main small,.bf,.bdica,.bmeta){color:#c5d2d8}html[data-theme=\"dark\"]:has(.amicus-home-header) :is(.grid a.card,.busca){background:#132835;color:#ebeff1;border-color:#2c4a5c}html[data-theme=\"dark\"]:has(.amicus-home-header) :is(.bq input,.bf select){background:#10222e;color:#ebeff1;border-color:#2c4a5c}\n.amicus-shell .amicus-actions [hidden]{display:none!important}\n"
CSS += "\n.amicus-shell .amicus-office{border-left:0!important;padding-left:0!important}\n.amicus-shell .amicus-office:before,.amicus-shell .amicus-context:before{content:\"/\";display:inline-block;margin-right:10px;color:var(--am-gold);font-weight:400}\n.amicus-shell .amicus-eyebrow{letter-spacing:.12em!important}\n.amicus-shell .amicus-appnav{display:flex;align-items:center;gap:9px;flex-wrap:wrap;min-width:0}\n.amicus-shell .amicus-appnav a{color:var(--am-fg)!important;text-decoration:none!important;font:600 12px Figtree,system-ui,sans-serif;white-space:nowrap}\n.amicus-shell .amicus-appnav a:hover{text-decoration:underline!important}\n.amicus-shell .amicus-appnav .amicus-sep{color:var(--am-gold);font-weight:400}\nbody>header.am-home-header.amicus-shell{grid-template-columns:auto minmax(0,1fr) auto;gap:0 16px}\nbody>header.am-home-header.amicus-shell>.amicus-appnav{grid-column:2;grid-row:1;padding:8px 0}\nbody>header.am-home-header.amicus-shell>.am-over-nav{grid-column:1/-1;grid-row:2;border-top:1px solid var(--am-line);padding:5px 0;justify-content:flex-start}\n@media(max-width:950px){body>header.am-home-header.amicus-shell{grid-template-columns:minmax(0,1fr) auto}body>header.am-home-header.amicus-shell>.amicus-actions{grid-column:2;grid-row:1}body>header.am-home-header.amicus-shell>.amicus-appnav{grid-column:1/-1;grid-row:2;border-top:1px solid var(--am-line)}body>header.am-home-header.amicus-shell>.am-over-nav{grid-row:3}}\n"
