CSS += "\n/* Amicus: navegação editorial na própria linha da marca, como #cmp-nav do Compendium. */\nbody>header.am-home-header.amicus-shell:has(.am-nav-apps){display:grid!important;grid-template-columns:auto minmax(0,1fr) auto;grid-template-rows:minmax(60px,auto);align-items:stretch;gap:0 12px;padding:4px 16px 0!important;position:sticky;top:0;z-index:20}\nbody>header.am-home-header.amicus-shell:has(.am-nav-apps)>.amicus-brand{align-self:center;grid-column:1;grid-row:1}\nbody>header.am-home-header.amicus-shell:has(.am-nav-apps)>.amicus-actions{align-self:center;grid-column:3;grid-row:1;min-width:0}\nbody>header.am-home-header.amicus-shell>.am-over-nav:has(.am-nav-apps){grid-column:2;grid-row:1;align-self:stretch;display:flex;align-items:stretch;flex-wrap:nowrap;gap:0;padding:0;margin:0;border:0;overflow-x:auto;overflow-y:hidden;scrollbar-width:thin}\n.am-home-header.amicus-shell .am-over-nav :is(.am-nav-apps,.am-nav-areas){display:flex;flex:none;align-items:stretch;flex-wrap:nowrap;gap:0;padding:0;border:0;counter-reset:amnav;border-left:1px solid var(--el)}\n.am-home-header.amicus-shell .am-over-nav :is(.am-nav-apps,.am-nav-areas) a{display:inline-flex;flex:none;align-items:center;justify-content:center;gap:8px;min-height:56px;min-width:0;margin:0;padding:0 12px;border:0;border-right:1px solid var(--el);border-radius:0;background:transparent;color:var(--ei);font:650 12px Figtree,\"Segoe UI\",system-ui,sans-serif;white-space:nowrap;text-decoration:none}\n.am-home-header.amicus-shell .am-over-nav .am-nav-apps a{counter-increment:amnav}\n.am-home-header.amicus-shell .am-over-nav .am-nav-apps a:before{content:counter(amnav,decimal-leading-zero);font:400 9px/1 var(--emono);color:var(--eo2);letter-spacing:.06em}\n.am-home-header.amicus-shell .am-over-nav .am-nav-areas a span{font:400 9px/1 var(--emono);color:var(--eo2)}\n.am-home-header.amicus-shell .am-over-nav a:hover,.am-home-header.amicus-shell .am-over-nav a:focus-visible{background:var(--ew);box-shadow:inset 0 3px 0 var(--eo)}\n.am-home-header.amicus-shell .am-over-nav a:focus-visible{outline:2px solid var(--eo);outline-offset:-3px}\n@media(max-width:1500px){.am-home-header.amicus-shell .am-over-nav :is(.am-nav-apps,.am-nav-areas) a{padding:0 8px;gap:5px;font-size:11px}}\n@media(max-width:760px){body>header.am-home-header.amicus-shell:has(.am-nav-apps){grid-template-columns:auto minmax(0,1fr) auto;gap:0 6px;padding:3px 8px 0!important}.am-home-header.amicus-shell .amicus-brand .amicus-office,.am-home-header.amicus-shell .amicus-brand .amicus-eyebrow{display:none!important}.am-home-header.amicus-shell .amicus-title{font-size:15px!important}.am-home-header.amicus-shell .amicus-actions .ac-u{max-width:55px}.am-home-header.amicus-shell .am-over-nav :is(.am-nav-apps,.am-nav-areas) a{min-height:48px}}\n"
JS = "\n(function(){\n'use strict';\nconst D=document, path=location.pathname, root=D.documentElement;\nconst editorial=/^\\/(?:amicus\\/(?:compendium|collegium|collectio)|modus|compendio|editor)(?:\\/|$)/.test(path);\nconst cognitio=/^\\/cognitio(?:\\/|$)/.test(path), collectio=/^\\/amicus\\/cortex(?:\\/|$)/.test(path);\nconst name=cognitio?'Cognitio':collectio?'CORTEX':/^\\/amicus\\/collectio(?:\\/|$)/.test(path)?'Collectio':/\\/collegium(?:\\/|$)/.test(path)?'Collegium':editorial?'Compendium':'Amicus Curiae';\nconst titleHref=cognitio?'/cognitio/':collectio?'/amicus/cortex/':name==='Collectio'?'/amicus/collectio/':name==='Collegium'?'/amicus/collegium/':editorial?'/amicus/compendium/':'/amicus/';\nconst icon=d=>'<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"'+d+'\"/></svg>';\nconst refresh=icon('M20 11a8 8 0 1 0-2.34 5.66M20 4v7h-7'),moon=icon('M20 14.5A8 8 0 0 1 9.5 4a8 8 0 1 0 10.5 10.5z'),sun=icon('M12 2v2m0 16v2M2 12h2m16 0h2M4.9 4.9l1.4 1.4m11.4 11.4 1.4 1.4m0-14.2-1.4 1.4M6.3 17.7l-1.4 1.4M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0z'),exit=icon('M9 4H6a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h3M14 8l4 4-4 4M18 12H9');\nconst star='<svg viewBox=\"319.34 233.85 63.70 71.05\" aria-hidden=\"true\"><path d=\"M349.96 304.90L349.96 287.14C349.96 280.71 344.75 275.50 338.33 275.50L319.34 275.50L327.63 283.46L336.49 283.46C342.58 283.46 347.51 288.40 347.51 294.49L347.51 302.55L349.96 304.90\"/><path d=\"M352.41 233.85L352.41 251.61C352.41 258.04 357.62 263.25 364.05 263.25L383.04 263.25L374.74 255.29L365.89 255.29C359.80 255.29 354.86 250.35 354.86 244.26L354.86 236.20L352.41 233.85\"/><path d=\"M349.96 261.41L349.96 243.65L341.39 251.88L341.39 259.58C341.39 266.00 336.18 271.21 329.75 271.21L321.25 271.21L319.34 273.05L338.33 273.05C344.75 273.05 349.96 267.84 349.96 261.41\"/><path d=\"M352.41 277.34L352.41 295.10L360.99 286.87L360.99 279.18C360.99 272.75 366.20 267.54 372.63 267.54L381.12 267.54L383.04 265.70L364.05 265.70C357.62 265.70 352.41 270.91 352.41 277.34\"/></svg>';\nlet session=null,ready=false,failed=false,pending=false;\nfunction button(label,markup,fn){const b=D.createElement('button');b.type='button';b.className='amicus-control';b.title=label;b.setAttribute('aria-label',label);b.innerHTML=markup;b.addEventListener('click',fn);return b;}\nfunction themeButton(){const b=button('Tema claro ou escuro',moon,()=>{const t=root.getAttribute('data-theme')==='dark'?'light':'dark';root.setAttribute('data-theme',t);try{localStorage.setItem('cmt-eq-tema',t)}catch(e){}b.innerHTML=t==='dark'?sun:moon;});b.innerHTML=root.getAttribute('data-theme')==='dark'?sun:moon;return b;}\nasync function logout(b){b.disabled=true;try{const r=await fetch('/api/login',{method:'DELETE',credentials:'same-origin',cache:'no-store'});if(!r.ok)throw Error('HTTP '+r.status);location.reload();}catch(e){b.disabled=false;alert('Não foi possível encerrar a sessão.');}}\nfunction fill(s){if(!s||!ready)return;if(s.dataset.sessionReady==='1')return;s.dataset.sessionReady='1';s.replaceChildren();if(session&&session.usuario){const u=D.createElement('span'),p=D.createElement('span');u.className='ac-u';u.textContent=session.usuario;p.className='ac-p';p.textContent=({editor:'Editor',avancado:'Avançado',equipe:'Equipe',desembargador:'Relator'})[session.perfil]||(session.gestor?'Gestor':session.perfil||'Equipe');if(session.desembargador)p.textContent='Relator';const out=button('Sair',exit,()=>logout(out));s.append(u,p,out);}else if(!failed){const a=D.createElement('a');a.className='amicus-enter';a.href='/exofficio/#inicio';a.textContent='Entrar';s.append(a);}s.hidden=!s.childElementCount;}\nfunction getSession(){fetch('/api/login',{credentials:'same-origin',cache:'no-store'}).then(async r=>{if(r.status===401)return null;if(!r.ok)throw Error('HTTP '+r.status);return r.json();}).then(j=>{session=j;ready=true;mount();}).catch(()=>{failed=true;ready=true;mount();});}\nfunction hide(el){if(el){el.classList.add('amicus-legacy-brand');el.style.setProperty('display','none','important');}}\nfunction mount(){\n const h=cognitio?D.querySelector('header#top'):collectio?D.querySelector('header.lx-nx'):editorial?D.querySelector('header.top.nx'):D.querySelector('body > header');\n if(!h)return;\n for(const a of h.querySelectorAll('a[href]')){try{const u=new URL(a.getAttribute('href'),location.href);if(/^\\/caput(?:\\/|$)/.test(u.pathname))a.remove();}catch(e){}}\n if(h.classList.contains('amicus-shell')){fill(h.querySelector('.amicus-session'));return;}\n h.classList.add('amicus-shell');if(!editorial&&!collectio&&!cognitio)h.classList.add('amicus-home-header');\n const row=collectio?h.querySelector('.lx-nx1')||h:h;\n const oldBrand=cognitio?h.querySelector('#marca'):collectio?h.querySelector('.lx-bc'):editorial?h.querySelector('.nx-bc'):null;\n const oldMark=collectio?h.querySelector('.lx-nx1 > .star'):editorial?h.querySelector('.brand.tw'):null;\n const oldOffice=Array.from(h.querySelectorAll('a[href]')).find(a=>/^\\/exofficio\\/?(?:#.*)?$/.test(a.getAttribute('href')));\n const nativeOfficeHidden=collectio&&!oldOffice;\n const brand=D.createElement('div');brand.className='amicus-brand';\n const crumb=oldBrand&&oldBrand.querySelector('.lx-cr');\n brand.innerHTML=star+'<div class=\"amicus-identity\"><a class=\"amicus-eyebrow\" href=\"/amicus/\">CMT / Amicus Curiae</a><div class=\"amicus-title-row\"><a class=\"amicus-title\" href=\"'+titleHref+'\" aria-current=\"page\">'+name+'<em>.</em></a>'+(nativeOfficeHidden?'':'<a class=\"amicus-office\" href=\"/exofficio/#inicio\">Ex Officio</a>')+'</div></div>';\n if(crumb){const c=D.createElement('span');c.className='amicus-context';c.textContent=crumb.textContent;if(crumb.id){c.id=crumb.id;crumb.removeAttribute('id');}brand.querySelector('.amicus-title-row').append(c);}\n if(editorial&&path.startsWith('/editor/')){const c=D.createElement('span');c.className='amicus-context';c.textContent='Editor';brand.querySelector('.amicus-title-row').append(c);}\n hide(oldBrand);hide(oldMark);\n hide(oldOffice);\n if(editorial)hide(h.querySelector('.nx-ir'));\n if(collectio)hide(h.querySelector('.lx-ir'));\n if(!editorial&&!collectio&&!cognitio)for(const e of Array.from(h.children))if(!e.classList.contains('am-home-overview'))hide(e);\n row.insertBefore(brand,row.firstChild);\n if(name==='Amicus Curiae'&&!h.querySelector('.am-nav-apps')){const nav=D.createElement('nav');nav.className='amicus-appnav';nav.setAttribute('aria-label','Aplicações do Amicus');const apps=[['Compendium','/amicus/compendium/'],['Cognitio','/amicus/cognitio/'],['Collegium','/amicus/collegium/'],['Collectio','/amicus/collectio/']];apps.forEach(([label,href],i)=>{if(i){const sep=D.createElement('span');sep.className='amicus-sep';sep.setAttribute('aria-hidden','true');sep.textContent='|';nav.append(sep);}const a=D.createElement('a');a.href=href;a.textContent=label;nav.append(a);});row.insertBefore(nav,brand.nextSibling);}\n const controls=D.createElement('div');controls.className='amicus-actions';\n const host=editorial?h.querySelector('.right')||h:collectio?h.querySelector('.ut,.cmt-ut')||row:cognitio?h.querySelector('#estado')||h:h;\n const rb=h.querySelector('#eq-atu,#atu'),tb=h.querySelector('#theme,#tema');\n if(rb){rb.classList.add('amicus-control');rb.title='Atualizar';rb.setAttribute('aria-label','Atualizar');controls.append(rb);}else controls.append(button('Atualizar',refresh,()=>location.reload()));\n if(tb){tb.classList.add('amicus-control');controls.append(tb);}else controls.append(themeButton());\n if(editorial){const chip=h.querySelector('#ac-chip');if(chip)controls.append(chip);}\n else{\n  const native=h.querySelector('#cog-chip,#eu');hide(native);\n  if(!nativeOfficeHidden){const s=D.createElement('span');s.className='amicus-session';s.hidden=true;controls.append(s);fill(s);}\n }\n host.append(controls);\n}\nif(!root.hasAttribute('data-theme')){try{root.setAttribute('data-theme',localStorage.getItem('cmt-eq-tema')||'light')}catch(e){root.setAttribute('data-theme','light')}}\nmount();if(!editorial)getSession();\nconst observer=new MutationObserver(records=>{if(pending||!records.some(r=>Array.from(r.addedNodes).some(n=>n.nodeType===1&&(n.matches?.('header.lx-nx,header.top.nx,header#top')||n.querySelector?.('header.lx-nx,header.top.nx,header#top')))))return;pending=true;requestAnimationFrame(()=>{pending=false;mount();});});if(collectio)observer.observe(D.body,{childList:true,subtree:true});\n})();\n"
ROUTES = (
    'amicus/index.html', 'cognitio/index.html',
    'amicus/cortex/index.html', 'amicus/cortex/previa/index.html',
    'amicus/cortex/classico/index.html', 'amicus/cortex/cg/index.html',
    'amicus/cortex/cmt/index.html', 'amicus/cortex/gc/index.html',
    'amicus/collectio/index.html', 'amicus/compendium/index.html', 'amicus/collegium/index.html',
    'modus/index.html', 'compendio/index.html', 'editor/index.html',
)
def apply(html):
    if 'id="amicus-shared-header"' in html:
        return html
    # Strip only the direct Caput shortcut in the actual editorial header.
    html = re.sub(r'<a\b[^>]*\bhref=["\'](?:https?://[^/"\']+)?/caput/?(?:[?#][^"\']*)?["\'][^>]*\btitle=["\']Abrir o Caput["\'][^>]*>.*?</a>', '', html, flags=re.I | re.S)
    if '</head>' not in html or '</body>' not in html:
        raise ValueError('Página sem head/body')
    html = html.replace('</head>', '<style id="amicus-shared-header">'+CSS+'</style>\n</head>', 1)
    before, sep, after = html.rpartition('</body>')
    return before+'<script>'+JS+'</script>\n'+sep+after

if __name__ == '__main__':
    root = Path(sys.argv[1])
    for route in ROUTES:
        p = root / route
        p.write_text(apply(p.read_text(encoding='utf-8')), encoding='utf-8')
        print('Amicus header:', route)
